  CREATE TABLE IF NOT EXISTS tmp (alarm_date DATETIME);
  SELECT input_date FROM userInput INTO @ldate;
  SET @y = YEAR(@ldate) + 1;
  test_loop : LOOP
    IF (YEAR(@ldate) = @y) THEN
      LEAVE test_loop
